styl:
.brad-full { border-radius: 32px !important; }
.white-bg { background-color: #fff; }
.middle-title { font-family: Helvetica !important;
  font-weight: 700;
  font-size: 32px;
  line-height: 42px;
  color: #393a44;
  vertical-align: middle; }
@media screen and (max-width: 600px) {
  .middle-title { font-size: 28px !important;
    line-height: 34px !important; }
}
.text { font-family: Helvetica !important;
  font-size: 18px;
  color: #393a44;
  letter-spacing: 0;
  line-height: 26px;
  font-weight: 400; }
.text.bold { font-weight: 700; }
.pb16 { padding-bottom: 16px; }
.pb44 { padding-bottom: 44px; }
.pt44 { padding-top: 44px; }
.orange-block { background: url("https://fsms.quadcode.com/storage/public/d6/o2/ua3ursrq72d917s0/bcg.png") center no-repeat;
  background-size: cover;
  background-color: #fff8f0;
  border-radius: 24px; }
.w40 { float: none;
  display: inline-block;
  width: 210px;
  vertical-align: bottom;
  padding: 24px 0 24px 32px; }
@media screen and (max-width: 600px) {
  .w40 { float: none !important;
    display: block !important;
    margin: 0 auto !important;
    width: auto !important; }
}
.right-img { float: none;
  display: inline-block;
  width: 214px !important;
  vertical-align: bottom; }
@media screen and (max-width: 600px) {
  .right-img { float: none !important;
    display: block !important;
    margin: 0 auto !important; }
}
